#!/bin/bash
# usage: measure.sh <candidate.lean> [version]  ; env STEP (default 250), HI (default 800 steps)
CAND=$1; VER=${2:-v4.31.0}
W="$PWD"; STEP=${STEP:-250}
mk() { { cat "$W/runtime_tmp/h/pre.lean"; echo "set_option maxHeartbeats $(( $1 * STEP )) in"; sed 's/^theorem interleaved_affine_gaps_imply_tensor_gaps/theorem test_thm/' "$CAND"; } > "$W/runtime_tmp/h/m_$$.lean"; }
try() { mk "$1"; out=$("$W/runtime_tmp/rt.sh" "$VER" "$W/runtime_tmp/h/m_$$.lean" 2>&1);
  if echo "$out" | grep -q "error:"; then
    if echo "$out" | grep -q "heartbeats"; then return 1; fi
    echo "$out" | grep "error:" ; return 2
  fi; return 0; }
try ${HI:-800}; rc=$?
if [ $rc -ne 0 ]; then echo "BASELINE FAIL rc=$rc (raise HI)"; exit 1; fi
lo=1; hi=${HI:-800}
while [ $((hi-lo)) -gt 1 ]; do
  mid=$(( (lo+hi)/2 ))
  try $mid; rc=$?
  if [ $rc -eq 0 ]; then hi=$mid; elif [ $rc -eq 1 ]; then lo=$mid; else echo "ERROR at $mid"; exit 1; fi
done
echo "minimal maxHeartbeats ~ $((hi*STEP))"
